assignments.value:
={{ $json.type === 'post.platform.failed'
  ? `A post failed on ${$json.data.platformPost.platform}: ${$json.data.platformPost.error?.message ?? 'unknown error'}\n> ${($json.data.post.text || '').slice(0, 200)}`
  : `Reconnect ${$json.data.account.platform} @${$json.data.account.username ?? ''} in Ampost to keep publishing: https://ampost.io/app` }}
